	static get Propertyrule() {
		return Schema.StructWithRest(
			Schema.Struct({
				inherits: Schema.Boolean.annotate({ description: "Whether the custom property is inherited." }),
				initialValue: Schema.optionalKey(
					Schema.Union([Parsedcomponent, Schema.Null]).annotate({
						description: "An optional initial value for the custom property.",
					}),
				),
				loc: Schema.StructWithRest(
					Schema.Struct({
						column: Schema.Number.annotate({
							description:
								"The column number within a line, starting at 1 for first the character of the line. Column numbers are counted in UTF-16 code units.",
							format: "uint32",
						})
							.check(Schema.isInt())
							.check(Schema.isGreaterThanOrEqualTo(0)),
						line: Schema.Number.annotate({ description: "The line number, starting at 0.", format: "uint32" })
							.check(Schema.isInt())
							.check(Schema.isGreaterThanOrEqualTo(0)),
						source_index: Schema.Number.annotate({
							description: "The index of the source file within the source map.",
							format: "uint32",
						})
							.check(Schema.isInt())
							.check(Schema.isGreaterThanOrEqualTo(0)),
					}),
					[Schema.Record(Schema.String, Schema.Unknown)],
				).annotate({ description: "A source location." }),
				name: Schema.String.annotate({ description: "The name of the custom property to declare." }),
				syntax: Schema.Union(
					[
						Schema.StructWithRest(
							Schema.Struct({ type: Schema.Literal("components"), value: Schema.Array(Syntaxcomponent) }),
							[Schema.Record(Schema.String, Schema.Unknown)],
						).annotate({ description: "A list of syntax components." }),
						Schema.StructWithRest(Schema.Struct({ type: Schema.Literal("universal") }), [
							Schema.Record(Schema.String, Schema.Unknown),
						]).annotate({ description: "The universal syntax definition." }),
					],
					{ mode: "oneOf" },
				).annotate({
					description:
						"A CSS [syntax string](https://drafts.css-houdini.org/css-properties-values-api/#syntax-strings) used to define the grammar for a registered custom property.",
				}),
			}),
			[Schema.Record(Schema.String, Schema.Unknown)],
		).annotate({
			description: "A [@property](https://drafts.css-houdini.org/css-properties-values-api/#at-property-rule) rule.",
		});
	}
