	static get Fontfeaturesubrule() {
		return Schema.StructWithRest(
			Schema.Struct({
				declarations: Schema.Record(
					Schema.String,
					Schema.Array(Schema.Number.annotate({ format: "int32" }).check(Schema.isInt())),
				).annotate({ description: "The declarations within the `@font-feature-values` sub-rules." }),
				loc: Schema.StructWithRest(
					Schema.Struct({
						column: Schema.Number.annotate({
							description:
								"The column number within a line, starting at 1 for first the character of the line. Column numbers are counted in UTF-16 code units.",
							format: "uint32",
						})
							.check(Schema.isInt())
							.check(Schema.isGreaterThanOrEqualTo(0)),
						line: Schema.Number.annotate({ description: "The line number, starting at 0.", format: "uint32" })
							.check(Schema.isInt())
							.check(Schema.isGreaterThanOrEqualTo(0)),
						source_index: Schema.Number.annotate({
							description: "The index of the source file within the source map.",
							format: "uint32",
						})
							.check(Schema.isInt())
							.check(Schema.isGreaterThanOrEqualTo(0)),
					}),
					[Schema.Record(Schema.String, Schema.Unknown)],
				).annotate({ description: "A source location." }),
				name: Schema.Literals([
					"stylistic",
					"historical-forms",
					"styleset",
					"character-variant",
					"swash",
					"ornaments",
					"annotation",
				]).annotate({
					description:
						"The name of the `@font-feature-values` sub-rule. font-feature-value-type = <@stylistic> | <@historical-forms> | <@styleset> | <@character-variant> | <@swash> | <@ornaments> | <@annotation>",
				}),
			}),
			[Schema.Record(Schema.String, Schema.Unknown)],
		).annotate({
			description:
				"A sub-rule of `@font-feature-values` https://drafts.csswg.org/css-fonts/#font-feature-values-syntax",
		});
	}
